def getAcceptedIssuers(self): 
    accepted_issuers = []
    for trust_manager in self.trust_managers:
        accepted_issuers.extend(trust_manager.getAcceptedIssuers())
    if not accepted_issuers:
        return None
    else:
        return accepted_issuers

